import type { CipherId, Division } from '../config/ciphers';
import { RULES } from '../config/rules';
import { SCHEDULE } from '../config/schedule';
import { pickQuote, type QuoteQuery } from '../data/quoteBank';
import { dailySeed, weekday } from '../lib/nyDate';
import { createRng } from '../lib/rng';

/**
 * Daily set selection. Phase 1 picks the cipher types and source quotes only;
 * keys and ciphertext are generated by the cipher engine in phase 2.
 */

export interface DailySlot {
  slot: string;
  cipher: CipherId;
  /** null for ciphers that are not built from a quote (Cryptarithm). */
  quoteId: string | null;
}

export interface DailySet {
  date: string;
  seed: string;
  division: Division;
  slots: DailySlot[];
}

// Placeholder length ranges; phase 2 replaces these with per-cipher, per-difficulty config.
function quoteQuery(cipher: CipherId, featured: boolean): QuoteQuery | null {
  if (cipher === 'cryptarithm') return null;
  if (cipher === 'xenocrypt') return { lang: 'es', minLetters: 15 };
  if (featured) return { lang: 'en', minLetters: 50, maxLetters: 120 };
  return { lang: 'en', minLetters: 20, maxLetters: 120 };
}

export function generateDailySet(date: string, division: Division = RULES.division): DailySet {
  const week = SCHEDULE[division];
  if (!week) throw new Error(`No daily schedule for Division ${division}`);
  const seed = dailySeed(date);
  const rng = createRng(seed);
  const day = week[weekday(date)]!;

  const entries: [string, CipherId, boolean][] = [
    ['featured', day.featured, true],
    ...day.others.map((c, i): [string, CipherId, boolean] => [`q${i + 1}`, c, false]),
  ];

  const slots = entries.map(([slot, cipher, featured]) => {
    const query = quoteQuery(cipher, featured);
    const quoteId = query ? pickQuote(rng.derive(`${slot}/quote`), query).id : null;
    return { slot, cipher, quoteId };
  });

  return { date, seed, division, slots };
}
